def sum_evens(numbers: list[int]) -> int:
    """Return the sum of even numbers in the list."""
    return sum(n for n in numbers if n % 2 == 0)


if __name__ == "__main__":
    print(sum_evens([1, 2, 3, 4, 5, 6]))

